import 'package:pos_app/database/app_database.dart';
final class DashboardMetrics {const DashboardMetrics({required this.salesCents,required this.operations,required this.fifoCostCents,required this.grossProfitCents,required this.expensesCents});final int salesCents;final int operations;final int fifoCostCents;final int grossProfitCents;final int expensesCents;int get resultCents=>grossProfitCents-expensesCents;}
final class ReportRepository {ReportRepository(this._db);final AppDatabase _db;Future<DashboardMetrics> today() async {final db=await _db.open();final day=DateTime.now().toUtc().toIso8601String().substring(0,10);final s=await db.rawQuery("SELECT COALESCE(SUM(total_cents),0) sales,COUNT(*) ops,COALESCE(SUM(fifo_cost_cents),0) cost,COALESCE(SUM(gross_profit_cents),0) profit FROM sales WHERE substr(sale_datetime,1,10)=? AND status='Confirmed'",[day]);final e=await db.rawQuery('SELECT COALESCE(SUM(amount_cents),0) expenses FROM expenses WHERE substr(expense_date,1,10)=?',[day]);return DashboardMetrics(salesCents:s.first['sales'] as int,operations:s.first['ops'] as int,fifoCostCents:s.first['cost'] as int,grossProfitCents:s.first['profit'] as int,expensesCents:e.first['expenses'] as int);}}
